#!/usr/bin/env node
// Generates lib/glossary-redirects.ts from scripts/data/glossary-redirects.csv.
//
// The glossary section (/glossary/<slug>, /fr/glossary/<slug>) was retired on
// 2026-09-19: every term now 301s to the broader article that covers it, or
// returns 410 where no same-locale article exists. The CSV is the single source
// of truth for that map; this script is the only thing that should touch the
// generated file. Middleware reads the table (see middleware.ts).
//
//   node scripts/gen-glossary-redirects.mjs          # regenerate
//   node scripts/gen-glossary-redirects.mjs --stdout # print instead of writing (used by the gate)
//   node scripts/check-glossary-redirects.mjs        # verify (targets exist, no chains)
import { readFileSync, writeFileSync } from "node:fs"
import { join, dirname } from "node:path"
import { fileURLToPath } from "node:url"

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..")
const CSV = join(ROOT, "scripts", "data", "glossary-redirects.csv")
const OUT = join(ROOT, "lib", "glossary-redirects.ts")

const lines = readFileSync(CSV, "utf8").trim().split("\n")
const header = lines.shift().split(",")
if (header.join(",") !== "locale,slug,status,target") {
  console.error(`unexpected CSV header: ${header.join(",")}`)
  process.exit(1)
}

const SLUG = /^[a-z0-9-]+$/
const entries = []
for (const line of lines) {
  const [locale, slug, status, target] = line.split(",")
  if (!["en", "fr"].includes(locale)) throw new Error(`bad locale: ${line}`)
  if (!SLUG.test(slug)) throw new Error(`bad slug: ${line}`)
  if (!["301", "410"].includes(status)) throw new Error(`bad status: ${line}`)
  if (status === "301" && !SLUG.test(target)) throw new Error(`301 without target: ${line}`)
  if (status === "410" && target) throw new Error(`410 with a target: ${line}`)
  const prefix = locale === "en" ? "" : `/${locale}`
  const from = `${prefix}/glossary/${slug}`
  entries.push(
    status === "301"
      ? `  ${JSON.stringify(from)}: { status: 301, to: ${JSON.stringify(`${prefix}/blog/${target}`)} },`
      : `  ${JSON.stringify(from)}: { status: 410 },`
  )
}

// The two index hubs are not in the CSV: they 301 to the equivalent blog hub.
const indexEntries = [
  `  "/glossary": { status: 301, to: "/blog" },`,
  `  "/fr/glossary": { status: 301, to: "/fr/blog" },`,
]

const body = `// GENERATED by scripts/gen-glossary-redirects.mjs from scripts/data/glossary-redirects.csv
// — do not edit by hand. Regenerate with: node scripts/gen-glossary-redirects.mjs
//
// The glossary section was retired 2026-09-19. Keys are the retired HTML paths
// (no trailing slash, no .md); middleware.ts also maps the .md twin of every
// key to the .md twin of its target. A 410 key returns a real 410 body.
// These rules stay live indefinitely (≥ 1 year) — do not prune them.

export type GlossaryRedirect = { status: 301; to: string } | { status: 410 }

export const GLOSSARY_REDIRECTS: Readonly<Record<string, GlossaryRedirect>> = {
${indexEntries.join("\n")}
${entries.join("\n")}
}
`
if (process.argv.includes("--stdout")) {
  process.stdout.write(body)
} else {
  writeFileSync(OUT, body)
  console.log(`glossary redirects → ${OUT}: ${entries.length} term rules + ${indexEntries.length} index rules`)
}
